using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<WeatherForecast> typedInfo = (JsonTypeInfo<WeatherForecast>)options.GetTypeInfo(typeof(WeatherForecast));
Console.WriteLine($"Got JsonTypeInfo for: {typedInfo.Type.Name}");

var forecast = new WeatherForecast { Date = DateTime.Now, Summary = "Warm", TemperatureC = 30 };
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
bool found = options.TryGetTypeInfo(typeof(UnknownType), out JsonTypeInfo? probeResult);
Console.WriteLine($"\nTryGetTypeInfo for UnknownType: found={found}, result={probeResult?.Type.Name ?? "(null)"}");

// Confirm it works for a known type too
bool found2 = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? probeResult2);
Console.WriteLine($"TryGetTypeInfo for WeatherForecast: found={found2}, result={probeResult2?.Type.Name ?? "(null)"}");

// Types
public record WeatherForecast
{
    public DateTime Date { get; init; }
    public string? Summary { get; init; }
    public int TemperatureC { get; init; }
}

public class UnknownType { public int X { get; set; } }

// Source-gen context that only knows about WeatherForecast
[JsonSerializable(typeof(WeatherForecast))]
public partial class MyContext : JsonSerializerContext;

